<template><el-table :data="summary" border stripe><el-table-column type="expand"><template #default="{row}"><div class="expand"><section><strong>简历证据</strong><p v-for="item in row.resumeEvidence" :key="item.id">{{ item.content }}</p><el-empty v-if="!row.resumeEvidence?.length" description="暂无简历证据" :image-size="42"/></section><section><strong>面试证据与来源问题</strong><div v-for="item in row.interviewEvidence" :key="item.id" class="source"><p>{{ item.content }}</p><small>来源问题：{{ item.relatedQuestion || '面试追问' }}</small></div><el-empty v-if="!row.interviewEvidence?.length" description="暂无面试证据" :image-size="42"/></section></div></template></el-table-column><el-table-column prop="competencyName" label="能力" min-width="150"/><el-table-column label="简历证据" min-width="230" show-overflow-tooltip><template #default="{row}">{{ row.resumeEvidence?.[0]?.content || '暂无' }}</template></el-table-column><el-table-column label="面试证据" min-width="250" show-overflow-tooltip><template #default="{row}">{{ row.interviewEvidence?.[0]?.content || '暂无' }}</template></el-table-column><el-table-column prop="strength" label="强度" width="80"/><el-table-column prop="confidence" label="置信度" width="90"><template #default="{row}">{{ row.confidence }}%</template></el-table-column><el-table-column label="风险" width="130"><template #default="{row}"><el-tag :type="row.risk==='无明显风险'?'success':'danger'">{{ row.risk }}</el-tag></template></el-table-column></el-table></template>
<script setup>defineProps({summary:{type:Array,default:()=>[]}});</script>
<style scoped>.expand{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:12px 32px}.expand section{padding:14px;background:#f7f9fc;border-radius:8px}.expand p{line-height:1.6;color:#4e5969}.source{padding-bottom:8px;border-bottom:1px dashed #dcdfe6}.source small{color:#909399}</style>
